644	  render(world: World, eyeX: number, eyeY: number, eyeZ: number, yaw: number, pitch: number,
645	    target: RenderTarget | null, worldTicks: number, elapsed: number, renderDistance: number): void {
646	    const gl = this.gl;
647	    this.eye = [eyeX, eyeY, eyeZ];
648	    this.yaw = yaw;
649	    this.pitch = pitch;
650	    this.frameTime = elapsed;
651	    const aspect = gl.drawingBufferWidth / Math.max(1, gl.drawingBufferHeight);
652	    perspective(this.proj, (70 * Math.PI) / 180, aspect, 0.05, 512);
653	    viewFromYawPitch(this.view, yaw, pitch, eyeX, eyeY, eyeZ);
654	    multiply(this.vp, this.proj, this.view);
655	    invert(this.invVp, this.vp);
656	    this.updateFrustum();
657	
658	    const time = ((worldTicks % 24000) + 24000) % 24000;
659	    const angle = (time / 24000) * Math.PI * 2;
660	    const sunDir: [number, number, number] = [Math.cos(angle), Math.sin(angle), 0.18];
661	    const sl = Math.hypot(...sunDir);
662	    sunDir[0] /= sl; sunDir[1] /= sl; sunDir[2] /= sl;
663	    const day = smoothstep(-0.16, 0.16, sunDir[1]);
664	    const skyTop = hexToRgb('#78a7ff').map(v => v * day) as [number, number, number];
665	    const fogDay = hexToRgb('#c0d8ff');
666	    const fogNight = hexToRgb('#0c0c16');
667	    const horizon: [number, number, number] = [
668	      fogNight[0] + (fogDay[0] - fogNight[0]) * day,
669	      fogNight[1] + (fogDay[1] - fogNight[1]) * day,
670	      fogNight[2] + (fogDay[2] - fogNight[2]) * day,
671	    ];
672	    const sunset = Math.exp(-Math.pow(sunDir[1] / 0.22, 2)) * (0.35 + 0.65 * (1 - day));
673	    const sunsetCol = hexToRgb('#da6333');
674	    for (let i = 0; i < 3; i++) horizon[i] = horizon[i] * (1 - sunset * 0.25) + sunsetCol[i] * sunset * 0.5;
675	
676	    this.renderShadowMap(world, sunDir, day, elapsed);
