997	  findSpawn(): { x: number, y: number, z: number, yaw: number } {
998	    const coast = this.findCoastSpawn();
999	    if (coast) return coast;
1000	    let best: { x: number, y: number, z: number } | null = null;
1001	    let bestScore = -1e9;
1002	    for (let r = 0; r <= 88; r += 4) {
1003	      const steps = r === 0 ? 1 : Math.min(72, Math.max(16, Math.round(r * 1.2)));
1004	      for (let a = 0; a < steps; a++) {
1005	        const ang = (a / steps) * Math.PI * 2;
1006	        const x = Math.round(Math.cos(ang) * r);
1007	        const z = Math.round(Math.sin(ang) * r);
1008	        const c = this.chunkAt(x >> 4, z >> 4);
1009	        if (!c) continue;
1010	        const h = c.heights[(z & 15) * 16 + (x & 15)];
1011	        const biome = this.getBiome(x, z);
1012	        const minH = biome === BIOME.beach ? SEA_LEVEL : SEA_LEVEL + 2;
1013	        if (h < minH || h > 132) continue;
1014	        const top = this.getBlock(x, h, z);
1015	        if (top !== this.ids.grass_block && top !== this.ids.sand) continue;
1016	        if (biome === BIOME.ocean || biome === BIOME.frozenOcean || biome === BIOME.mountains) continue;
1017	        let clear = true;
1018	        for (let dy = 1; dy <= 5; dy++) {
1019	          const above = this.getBlock(x, h + dy, z);
1020	          if (above !== 0 && this.rocks.solid[above]) { clear = false; break; }
1021	        }
1022	        if (!clear) continue;
1023	        let trees = 0;
1024	        for (let dz = -4; dz <= 4; dz++) {
1025	          for (let dx = -4; dx <= 4; dx++) {
1026	            for (let dy = 1; dy <= 14; dy++) {
1027	              const id = this.getBlock(x + dx, h + dy, z + dz);
1028	              if (this.isLeaves(id)) trees++;
1029	            }
1030	          }
1031	        }
1032	        if (trees > 24) continue;
1033	        let water = 0;
1034	        for (let k = 0; k < 16; k++) {
1035	          const aa = (k / 16) * Math.PI * 2;
1036	          for (let d = 8; d <= 40; d += 4) {
1037	            if (this.getBlock(Math.round(x + Math.cos(aa) * d), SEA_LEVEL, Math.round(z + Math.sin(aa) * d)) === this.ids.water) water++;
1038	          }
1039	        }
1040	        let open = 0;
1041	        for (let k = 0; k < 8; k++) {
1042	          const aa = (k / 8) * Math.PI * 2;
1043	          const cc = this.chunkAt((x + Math.round(Math.cos(aa) * 24)) >> 4, (z + Math.round(Math.sin(aa) * 24)) >> 4);
1044	          if (!cc) continue;
1045	          const hh = cc.heights[((z + Math.round(Math.sin(aa) * 24)) & 15) * 16 + ((x + Math.round(Math.cos(aa) * 24)) & 15)];
